function browserInterval(events, start, end) {
  const starts = events.filter(({ event }) => event.source === "browser" && event.name === start);
  const ends = events.filter(({ event }) => event.source === "browser" && event.name === end);
  if (starts.length !== 1 || ends.length !== 1)
    return null;
  const a = starts[0].event, b = ends[0].event;
  if (![a.seq, b.seq].every((value) => Number.isSafeInteger(value) && value >= 0) || b.seq <= a.seq || ![a.elapsed_ms, b.elapsed_ms].every((value) => Number.isFinite(value) && value >= 0) || b.elapsed_ms < a.elapsed_ms)
    return null;
  return Math.round((b.elapsed_ms - a.elapsed_ms) * 1000) / 1000;
}
